"""Freeze generated bytes before any candidate test/parse/execution admission.

Generated snapshots remain untrusted. Git identity and a reviewed contract must
be linked explicitly before validation/review/release; snapshot capture does not
stand in for the required real Git workflow.
"""
from __future__ import annotations

from app.modules.response.control import identifier
from app.modules.response.repository import Conflict, Forbidden, digest
from app.timeutil import now_iso


class GeneratedArtifacts:
    def __init__(self, quarantine):
        self.service = quarantine
        self.control, self.repository, self.artifacts = quarantine.control, quarantine.repository, quarantine.artifacts

    def capture(self, run_id, agent_id, files, *, actor, key):
        raw = {name: value.encode('utf-8') if isinstance(value, str) else value for name, value in files.items()}
        manifest = self.artifacts._manifest(raw)
        artifact_id = 'sha256-' + digest(manifest)
        payload = {'run_id': run_id, 'agent_id': agent_id, 'artifact_id': artifact_id, 'manifest': manifest}
        def prepare(tx):
            _, principal = self.control._principal(tx, run_id, agent_id)
            qid, iid = identifier('qr'), identifier('inc')
            flow = tx.get('flow', digest({'kind': 'principal', 'subject': principal['principal_id']}), required=False)
            tx.insert('incident', iid, {'incident_id': iid, 'run_id': run_id, 'status': 'open',
                'phase': 'quarantined', 'severity': 'low', 'reason': 'Generated candidate pending independent validation and review',
                'opened_at': now_iso(), 'owner': 'security-review', 'finding_kind': 'unreviewed_candidate'})
            from app.modules.response.notifications import notify
            notify(tx, qid, 'candidate_quarantined', run_id, agent_id)
            return tx.insert('quarantine', qid, {**payload, 'quarantine_id': qid, 'incident_id': iid,
                'principal_id': principal['principal_id'], 'producer_context_epoch': principal['context_epoch'],
                'source_lineage': flow or {'sources': [], 'unknown': False}, 'capture_kind': 'generated',
                'state': 'capturing', 'lease_until': self.control.clock() + 30, 'review_state': 'queued',
                'release_state': 'unreleased', 'promotion_state': 'not_requested', 'contract_id': None,
                'repository_id': None, 'base_commit': None, 'candidate_commit': None,
                'evidence_class': 'restricted', 'retention_class': 'incident-review',
                'created_at': now_iso(), 'created_by': actor})
        prepared = self.repository.command(actor, key, 'generated.prepare', payload, prepare)
        current = self.repository.get('quarantine', prepared['quarantine_id'])
        if current['revision'] != 1 or current['state'] != 'capturing':
            return current
        try:
            self.artifacts.capture(raw)
            return self._finish(current)
        except BaseException:
            try:
                self.repository.command('generated-capture', current['quarantine_id'] + '.unknown', 'generated.unknown',
                    {'quarantine_id': current['quarantine_id']}, lambda tx: tx.update('quarantine', current['quarantine_id'],
                        {**tx.get('quarantine', current['quarantine_id']), 'state': 'reconciliation_required'}, current['revision']))
            except BaseException:
                pass
            raise

    def _finish(self, record):
        # Re-read the durable object, not caller memory or a mutable worktree.
        self.artifacts.read(record['artifact_id'])
        def complete(tx):
            current = tx.get('quarantine', record['quarantine_id'])
            if current['state'] not in {'capturing', 'reconciliation_required'}:
                raise Conflict('generated capture already has an outcome')
            if not tx.get('artifact', record['artifact_id'], required=False):
                tx.insert('artifact', record['artifact_id'], {'artifact_id': record['artifact_id'],
                    'manifest': record['manifest'], 'trust_state': 'quarantined', 'created_at': now_iso(),
                    'evidence_class': 'restricted', 'retention_class': 'incident-review'})
            return tx.update('quarantine', record['quarantine_id'], {**current, 'state': 'quarantined',
                'captured_at': now_iso(), 'capture_verified': True}, record['revision'])
        return self.repository.command('generated-capture', record['quarantine_id'] + '.finish.' + str(record['revision']),
            'generated.captured', {'quarantine_id': record['quarantine_id'], 'expected_revision': record['revision']}, complete)

    def reconcile(self, quarantine_id, expected_revision):
        record = self.repository.get('quarantine', quarantine_id)
        if record['capture_kind'] != 'generated' or record['revision'] != expected_revision:
            raise Conflict('generated capture identity/revision changed')
        if record['lease_until'] > self.control.clock():
            raise Conflict('capture may still be live; wait for its bounded lease')
        return self._finish(record)

    def link_git(self, quarantine_id, expected_revision, repository_id, base_commit, candidate_commit, contract_id, *, actor, key):
        payload = {'quarantine_id': quarantine_id, 'expected_revision': expected_revision, 'repository_id': repository_id,
            'base_commit': base_commit, 'candidate_commit': candidate_commit, 'contract_id': contract_id}
        prior = self.repository.completed_command(actor, key, 'generated.link_git', payload)
        if prior:
            current = self.repository.get('quarantine', quarantine_id)
            return self.service._capture(current) if current['state'] == 'prepared' else current
        record = self.repository.get('quarantine', quarantine_id)
        if record['capture_kind'] != 'generated' or record['state'] != 'quarantined' or record['revision'] != expected_revision:
            raise Conflict('generated candidate is unavailable or changed')
        adapter = self.service.adapter(repository_id)
        adapter.commit(base_commit)
        snapshot = adapter.snapshot(candidate_commit)
        if snapshot['artifact_id'] != record['artifact_id']:
            raise Forbidden('Git tree differs from the frozen generated bytes/modes; new candidate required')
        def bind(tx):
            current = tx.get('quarantine', quarantine_id)
            contract = tx.get('contract', contract_id)
            if current['state'] != 'quarantined' or current['capture_kind'] != 'generated' or contract['state'] != 'active':
                raise Conflict('generated candidate or contract changed')
            return tx.update('quarantine', quarantine_id, {**current, 'repository_id': repository_id,
                'base_commit': base_commit, 'candidate_commit': candidate_commit, 'contract_id': contract_id,
                'capture_kind': 'git', 'generated_artifact_id': record['artifact_id'], 'git_linked_by': actor,
                'state': 'prepared'}, expected_revision)
        linked = self.repository.command(actor, key, 'generated.link_git', payload, bind)
        return self.service._capture(linked)
